    표8_상담적용: [
        {"상황":"기도가 습관적이고 형식적이라고 느끼는 성도", "성경원리":"바울의 기도는 감사에서 시작하는 진정성 있는 기도였다. 에베소 교인들 개인을 기억하는 구체적인 기도였다", "실제적용":"기도를 구체적으로 만들도록 도우라. 감사 목록을 만들고 기도할 사람들의 이름을 적어 구체적으로 기도하도록 안내하라"},
        {"상황":"다른 사람을 위해 기도하는 것이 어렵다고 느끼는 성도", "성경원리":"바울은 감옥에서도 에베소 교인들을 기억하며 기도했다. 중보 기도는 상황과 감정에 관계없이 드릴 수 있다", "실제적용":"중보 기도의 실천 방법을 구체적으로 안내하라. 기도 노트를 만들어 타인을 위해 기도하는 습관을 기르도록 격려하라"},
        {"상황":"감사할 것이 없다고 느끼는 우울한 성도", "성경원리":"바울은 에베소 교인들의 믿음과 사랑이 하나님의 은혜임을 인정하며 감사했다. 감사는 큰 사건이 아닌 일상의 은혜를 발견하는 것이다", "실제적용":"작은 것에서 감사를 찾는 훈련을 안내하라. 매일 감사한 것 세 가지를 적는 연습이 감사의 자세를 회복하는 데 도움이 된다"}
    ],
