        {"영어원문":"This is not only in this world but also in the world to come: his dominion is everlasting.", "한국어번역":"이것은 이 세상뿐만 아니라 오는 세상에서도 그러합니다. 그의 통치는 영원합니다.", "핵심통찰":"그리스도의 왕권은 현재와 미래 모두에 걸쳐 영원함"},
        {"영어원문":"No name but that of God himself is above the name of Jesus.", "한국어번역":"하나님 자신의 이름 외에는 어떤 이름도 예수의 이름보다 높지 않습니다.", "핵심통찰":"예수 이름의 절대적 권위를 강조"}
