        {"구절":"사 9:6-7", "연결점":"그 정사와 평강의 더함이 무궁하며 — 메시아의 통치권 예언", "구분":"구약"},
        {"구절":"단 7:13-14", "연결점":"권세와 영광과 나라를 받으니 모든 백성과 나라들이 그를 섬기는 통치 — 그리스도 즉위의 예언", "구분":"구약"},
        {"구절":"시 110:1", "연결점":"원수들이 발등상이 될 때까지 오른편에 앉으라 — 만물 복종의 예언", "구분":"구약"},
        {"구절":"골 1:18", "연결점":"그는 몸인 교회의 머리라 — 직접적 병행 구절", "구분":"신약"},
        {"구절":"엡 4:15-16", "연결점":"머리인 그리스도에게까지 자랄지라 그에게서 온 몸이 연결되어 — 머리로부터 생명 공급 원리", "구분":"신약"},
        {"구절":"고전 15:27", "연결점":"만물을 그 발 아래 두셨다 하셨으니 — 동일한 시편 8:6 인용", "구분":"신약"},
        {"구절":"히 2:8", "연결점":"만물로 그 발 아래 복종케 하셨느니라 하셨으니 — 시편 8편의 그리스도 적용", "구분":"신약"}
