    표6_설교자료: [
        {"대지":"제목", "내용":"죽었던 자를 살리신 하나님의 기적", "예화_적용":"심폐소생술로 살아난 사람의 이야기를 통해 영적 살리심의 기적을 소개"},
        {"대지":"서론", "내용":"사람이 죽으면 스스로 살아날 수 없음. 영적으로도 마찬가지. 바울은 우리가 허물과 죄로 영적으로 죽어 있었다고 선언함. 그런데 놀라운 일이 일어났다. 하나님이 우리를 살리셨음!", "예화_적용":"중환자실의 환자가 의사의 도움 없이는 살 수 없듯, 영적으로 죽은 자는 하나님의 살리심 없이는 살아날 수 없음"},
        {"대지":"1대지: 죽음의 진단 (허물과 죄)", "내용":"바울은 두 가지 단어로 인간의 영적 상태를 진단함. 허물(παράπτωμα)은 하나님의 길에서 넘어짐이고, 죄(ἁμαρτία)는 하나님의 기준에서 빗나감. 이것이 우리의 본래 상태", "예화_적용":"의사가 정확한 진단 없이 치료할 수 없듯, 죄의 실상을 알아야 은혜의 가치를 알 수 있음"},
        {"대지":"2대지: 죽음의 심각성 (완전한 무능)", "내용":"영적 죽음은 하나님과의 완전한 단절을 의미함. 죽은 자는 어떤 선도, 기도도, 회개도 스스로 할 수 없음. 이것이 은혜가 필요한 이유", "예화_적용":"죽은 사람은 아무 반응도 없음 — 영적으로 죽은 인간도 하나님의 살리심 없이는 반응할 수 없음"},
        {"대지":"3대지: 살리심의 기적 (하나님의 은혜)", "내용":"죽었던 우리를 하나님이 살리셨다. 이 살리심은 전적으로 하나님의 주권적 은혜의 역사임. 우리는 이 은혜의 수혜자임을 기억해야 함", "예화_적용":"거듭난 체험 — 하나님이 살리셨을 때의 그 감격과 감사를 회복하는 시간"},
        {"대지":"결론", "내용":"나는 원래 허물과 죄로 죽었던 자였으나 하나님이 살리셨다. 이 사실이 내 삶의 가장 큰 기적임. 이 기적에 감사하며, 새 생명을 받은 자로서 살아가자", "예화_적용":"새 생명을 받은 자의 삶은 달라야 함 — 죽었다가 살아난 자의 감사와 헌신"}
    ],
