        {"상황":"현실의 어려움으로 신앙이 좌절되고 하나님의 뜻을 의심하는 성도", "성경원리":"성도의 현재적 위치가 이미 하늘에 있으므로, 땅의 어려움이 최종 현실이 아님. 영적 위치가 물질적 상황보다 더 실재함", "실제적용":"골 3:1-4을 통해 위의 것을 바라보는 영적 관점을 회복하도록 안내하고, 현재 상황을 하늘 관점으로 재해석하는 훈련"},
        {"상황":"세상의 유혹과 죄에 반복적으로 빠지는 성도", "성경원리":"하늘에 앉혀진 신분을 기억하면 세상의 유혹에 대한 저항력이 생김. 신분이 행동의 동기가 됨", "실제적용":"'나는 하늘에 앉혀진 자인데 이 죄가 나에게 어울리는가?'라는 정체성 질문을 통해 죄와의 싸움에서 신분을 활용하는 방법 안내"}
