        {"대지":"서론", "내용":"우리가 구원받은 것이 단지 우리 자신을 위한 것이 아님. 하나님은 우리의 구원을 통해 오는 모든 세대에 자신의 은혜의 풍성함을 나타내려 하심. 나의 구원이 우주적 목적의 일부임", "예화_적용":"박물관에 전시된 작품처럼 성도 각자가 하나님의 은혜를 전시하는 작품임"},
        {"대지":"1대지: 은혜의 지극히 풍성함 (크기)", "내용":"ὑπερβάλλον — 측량할 수 없는 풍성함. 하나님의 은혜는 인간의 죄보다 더 크고, 모든 인간의 필요보다 더 충분하고, 모든 세대를 채울 만큼 넘침", "예화_적용":"롬 5:20 죄가 더한 곳에 은혜가 더욱 넘쳤나니 — 은혜의 풍성함은 죄의 깊이보다 깊음"},
        {"대지":"2대지: 자비하심으로 (성품)", "내용":"이 은혜는 하나님의 자비하심(χρηστότης)에서 흘러나옴. 자비로우신 하나님의 성품이 구원의 원천임. 우리의 구원은 하나님의 성품의 표현", "예화_적용":"좋으신 하나님 — 하나님의 자비가 얼마나 실제적으로 삶에 나타나는지"},
        {"대지":"3대지: 오는 세대에 나타냄 (목적)", "내용":"나의 구원이 오는 세대에 하나님의 은혜를 나타내는 목적을 가짐. 내 삶이 미래 세대에게 하나님의 은혜의 증거가 될 수 있음", "예화_적용":"신앙의 유산 — 우리의 신앙이 다음 세대에 하나님의 은혜를 전달하는 통로가 됨"},
        {"대지":"결론", "내용":"나의 구원은 단순히 내 죄 사함이 아니라 우주적 목적의 일부임. 나를 통해 하나님의 은혜가 나타나는 삶을 살자. 이것이 구원받은 자의 사명임", "예화_적용":"매일의 삶에서 하나님의 은혜를 나타내는 구체적인 방법 — 용서, 사랑, 섬김"}
