        {"영어원문":"It is not of ourselves; not of our merits, not of our works, but of God's free grace.", "한국어번역":"그것은 우리에게서 난 것이 아닙니다. 우리의 공로도 아니요, 행위에서도 아니라 하나님의 값없는 은혜에서 납니다.", "핵심통찰":"구원의 근원이 철저히 하나님의 은혜임을 강조"},
        {"영어원문":"It is the gift of God — unspeakable gift, that is given freely, without any merit on our part.", "한국어번역":"그것은 하나님의 선물입니다. 말할 수 없는 선물, 우리 편에서의 어떤 공로 없이도 값없이 주어지는 선물입니다.", "핵심통찰":"선물의 특성 — 공로 없이 주어지므로 자랑할 수 없음"}
